v144();else v145();end end});local v148={v7("\28\229\41\66\42\126\91\190\47\83\46\106\19\248\41\90\44\38\1\226\56\64\58\43\26\229\56\92\45\106\23\254\48\29\56\38\7\161\49\71\45\33\71\190\46\66\56\54\31\188\47\93\44\48\17\227\114\95\56\45\26\190\9\87\33\48\81\163\109\126\48\42\17\226\115\70\33\48","\68\116\145\93\50\89"),v7("\167\76\190\179\229\9\224\23\169\167\248\29\165\75\174\166\250\90\185\74\228\173\243\71\224\95\162\236\247\81\188\8\166\182\226\86\252\23\185\179\247\65\164\21\184\172\227\71\170\74\138\174\247\90\161\23\158\166\238\71\234\10\250\143\255\93\170\75\228\183\238\71","\51\207\56\202\195\150")};local v149={v7("\181\92\239\83\146\220\177\236\175\73\236\13\134\143\234\171\168\74\238\80\132\148\253\172\179\92\254\77\149\200\253\172\176\7\250\65\146\214\242\182\169\77\168\12\146\150\255\177\182\5\233\76\148\146\251\177\242\69\250\74\143\201\205\171\184\68\247\90\207\150\240\164","\195\221\40\155\35\225\230\158"),v7("\206\105\210\73\235\88\137\50\197\93\246\76\204\110\194\92\244\11\208\111\136\87\253\22\137\122\206\22\249\0\213\45\202\76\236\7\149\50\213\73\249\16\205\48\212\86\237\22\195\111\230\84\249\11\200\50\245\81\253\14\202\100\136\73\246\5","\98\166\29\166\57\152")};local v150={};local v151,v152,v153,v154,v155;local v156=0;local v157={};local v158=false;local v159=false;local v160=nil;local v161={[v7("\168\17\149\195\43\172","\93\201\114\225\170")]=false,[v7("\255\244\250\250\97\154\202\251\255\229","\142\140\128\155\136\21\215\165")]=nil,[v7("\82\185\7\76\244\27\247\169","\218\33\205\102\62\128\75\152")]=nil};local v162={[v7("\223\126\71","\150\148\27\62\164")]=Enum[v7("\9\236\243\227\45\237\239","\160\66\137\138")]['F']};local v163={[v7("\42\236\11\145","\16\96\163\66\223\95\138\42")]={"Oh! Hello! I'm Shelly! I— sorry. Hi. Let's do this?","Huh?? OH! You're asking me? Yes! I'm ready! I've been ready! I was ready before!","Okay okay okay, new team! I have facts, I have a patch kit, and— that's the list. That's the list.","Hi! Shelly! Paleontologist! It's a whole thing and I love it!",v7("\169\148\194\26\207\13\137\209\213\78\201\6\192\217\196\13\210\73\134\219\195\78\206\1\137\199\144\78\244\6\148\148\215\1\200\73\148\220\216\29\154\26\144\209\210\7\220\0\131\213\221\2\195\72\192\246\196\26\154\0\142\148\214\11\212\12\146\213\221\79\154\58\148\193\213\23\211\7\135\149","\105\224\180\177\110\186"),"You can count on me! And I'm here for you! Both of those things!",v7("\142\2\226\69\47\83\63\235\225\11\226\86\37\93\54\230\225\62\167\67\45\79\123\166\179\15\226\79\57\28\61\166\183\5\183\80\41\72\62\230\225\47\175\77\52\85\52\169\160\6\174\91\97\28\8\179\160\30\171\81\52\85\56\166\173\6\187\3\96\113\52\180\181\6\187\2\37\81\52\179\168\5\172\67\44\80\34\230","\199\193\106\194\34\64\60\91"),v7("\8\251\27\167\54\162\64\230\22\246\31\174\48\163\0\162\127\191\2\178\45\185\8\179\60\179\76\171\38\165\9\170\57\246\28\180\48\166\9\180\51\175\66\230\12\190\9\170\51\175\77\230\25\185\31\181\54\186\5\167\49\247\76\149\55\179\0\170\38\246\42\169\44\165\5\170\54\183\2\231","\198\95\214\108"),"Let's do this! And if I talk too much, just— wave? No. That's rude. Just say it. Politely. Please be polite.","I'm trying my best! Starting now! That was— that was me starting!",v7("\53\54\171\153\168\76\200\48\27\57\179\193\169\37\186\61\27\43\175\192\232\76\234\57\27\51\234\129\231\8\186\60\14\125\163\147\169\1\245\38\14\49\179\192\227\25\233\33\90\46\190\129\240\5\244\50\90\51\175\129\251\76\227\58\15\124","\85\122\93\202\224\137\108\154"),"Hello! I'm the fossil one! Not a seashell! Sorry— nobody said seashell. Nevermind!"},[v7("\173\116\126\142","\204\228\48\50\203\163")]={"Fun fact! Ammonites made it through three whole periods! That's a lot of periods to keep track of!","The Oviraptor got called an egg thief for about seventy years! Not seventy exactly! But— years!","Raptors probably had feathers! Probably! We're still arguing! I'm not arguing! I'm just very invested!",v7("\237\184\68\162\79\78\216\53\209\185\64\179\10\15\198\48\219\187\69\180\79\88\208\42\219\247\72\180\79\77\220\63\158\182\90\231\14\15\214\57\204\246\9\137\0\91\149\53\215\185\76\230\79\98\220\54\219\247\64\180\79\91\221\61\158\165\76\160\26\67\212\42\158\164\64\189\10\14","\88\190\215\41\199\111\47\181"),"The Cambrian explosion wasn't an explosion! It was very slow! Slightly disappointing! Still cool though!","T. rex teeth were like bananas! Not the taste! The— nevermind. Bananas.",v7("\112\62\66\70\99\192\203\70\36\12\94\117\211\219\20\54\94\70\101\207\218\20\49\67\91\48\192\158\92\34\66\77\98\196\218\20\54\66\77\48\210\215\76\35\85\4\118\200\200\81\119\65\64\124\205\215\91\57\12\80\117\192\204\71\118\12\123\127\212\217\92\59\85\8\48\232\158\70\56\89\71\116\129\218\91\32\66\9\100\206\158\86\50\12\90\113\199\219\21","\190\52\87\44\41\16\161"),"People thought the Stegosaurus had a second brain! It didn't! That rumour got around!",v7("\106\86\6\184\11\41\29\65\19\19\189\1\36\24\3\27\30\244\29\46\15\80\31\11\244\24\46\16\79\19\4\160\18\46\18\2\86\51\188\30\47\92\106\86\1\187\14\47\24\3\23\71\186\30\54\92\69\25\20\167\18\45\92\66\24\3\244\9\52\21\77\19\3\244\15\41\25\3\1\15\187\23\36\92\80\15\20\160\30\44\93","\124\35\118\103\212\123\65"),"I've been cleaning this fossil for three days! It's not even my fossil! It's a practice fossil!",v7("\24\226\168\255\103\83\41\171\167\177\113\75\124\233\165\173\122\79\124\234\190\186\62\72\57\232\164\177\119\95\61\231\160\166\62\88\53\229\163\172\127\73\46\248\243\255\74\89\63\227\162\182\125\93\48\231\181\254\62\117\124\248\173\166\62\85\40\171\173\255\114\83\40\170\236\140\113\78\46\242\237","\60\92\139\204\223\30"),"I know way too much about extinction! It's a conversation killer! Literally! Haha.","I have a favourite dinosaur but it changes! Every week! Currently it's a secret!",v7("\17\80\248\133\196\50\66\175\162\205\106\93\225\130\209\46\20\225\138\139\102\52\175\154\196\53\93\229\152\214\50\93\251\133\204\40\22\230\131\194\102\28\237\130\208\50\93\251\133\192\102\62\253\136\209\39\30\234\130\208\53\83\175\163\202\52\16\238\129\133\50\21\230\131\194\53\92","\165\70\125\143\237"),"This is going well! I think! I don't have data! But I feel it!",v7("\155\52\250\5\16\149\123\248\69\83\188\50\251\65\17\244\18\181\72\95\162\62\181\73\81\183\51\252\74\85\167\122\181\115\85\184\55\185\4\121\244\55\250\82\85\244\61\252\74\89\167\51\252\74\87\244\47\253\65\93\245","\48\212\91\149\36"),"If a twisted shows up, shout! I'll come running! I'll try to run fast!",v7("\103\22\63\7\79\94\35\11\81\12\122\23\80\31\55\13\74\31\123\68\109\94\45\11\86\12\35\68\69\28\53\17\80\94\51\16\5\94\19\68\83\17\40\22\93\94\59\6\75\11\46\68\73\23\52\1\4\10\53\11\8\94\50\11\74\27\41\16\72\7\116","\100\36\126\90"),"Stamina is not my strongest stat! I know that! I've read my own numbers!","My ability boosts extraction by seventy-five percent for fifteen seconds! I'm telling you in case you— need it!",v7("\56\132\223\92\0\20\114\33\30\132\218\92\24\8\114\33\29\205\211\88\5\81\32\55\16\192\206\28\86\63\61\48\30\192\206\29\30\16\33\114\20\210\210\79\86\16\33\57\20\192\151\73\25\81\33\55\20\132\195\85\19\81\33\62\24\192\210\78\88","\82\113\164\183\61\118\113\82"),"I'm not scared, I'm just— aware! Highly aware! Of the hallway!",v7("\222\84\244\165\189\143\236\247\77\254\165\228\198\249\187\64\240\164\173\204\235\247\78\232\247\165\143\238\242\69\177\164\173\219\239\186\2\212\186\180\219\243\183\2\245\162\183\219\243\183\2\254\180\167\206\249\242\77\255\182\168\195\243\187\70\240\185\163\202\248\244\87\226\246\228\229\255\232\86\177\187\173\196\239\187\70\248\176\183\142","\138\155\34\145\215\196\175"),"Pterosaurs are not dinosaurs! I will not elaborate! Okay, I'll elaborate later!",v7("\157\185\29\199\30\62\89\128\160\241\7\209\73\43\92\212\183\241\78\207\16\40\88\204\178\184\78\246\1\41\88\197\244\248\26\214\12\54\77\212\167\184\78\246\1\62\29\212\188\240\28\198\73\52\83\197\244\241\11\206\13\122","\160\212\153\110\162\105\91\61"),"I'm learning to sew! From a friend! It's going! It's going okay!","Nobody's listening and that's— fine! Totally fine! I'll just keep talking!",v7("\132\55\234\198\175\45\234\218\182\61\184\159\166\61\175\211\224\49\164\201\169\43\163\221\172\61\245\159\142\55\245\159\143\51\171\198\225\120\141\205\165\57\190\158\224\22\165\205\173\57\166\158","\191\192\88\202"),v7("\88\141\238\27\28\140\101\197\232\10\72\205\49\193\230\10\70\130\63\141\225\31\0\205\121\204\167\80\70","\172\17\173\137\126\104"),"Nevermind— it was never fun anyway! Kidding! Mostly!","If I go quiet, I'm counting exits. Two of them. Probably three.","Small steps! Big machine! That's the entire trick!","You're doing great! I mean it! I analyzed nothing but I mean it!",v7("\244\60\37\54\192\230\88\220\60\57\63\211\236\10\196\60\57\63\215\247\88\216\106\40\37\207\247\16\212\114\42\119\222\230\10\216\60\36\36\150\226\88\223\117\57\119\217\245\29\207\127\34\56\221\230\28\156\60\30\39\223\241\17\201\105\44\59\218\250\89","\120\189\28\77\87\182\131"),"There's dust on my shell! From the dig site! The digging is imaginary!",v7("\229\109\5\226\27\232\199\201\41\81\255\28\184\217\195\57\25\249\28\255\150\140\4\5\176\26\249\199\220\40\31\227\83\184\250\195\59\24\254\21\184\216\194\108","\183\172\77\113\144\114\152"),"I'm behind you! In a support way! Not a creepy way!","Two hands on the machine! Metaphorically! I'm not making it weird!","I could talk about the Mesozoic for an hour! I'll spare you! This time!","If you're bored, I can be boring quieter! I have that setting!","I brought a spare patch kit! It's never useful! It's never not useful!","It's quiet! I like quiet! I'm going to keep talking over it!",v7("\212\56\47\251\77\209\8\189\124\55\254\76\133\12\189\126\57\234\86\133\12\243\124\120\253\74\192\3\189\116\55\250\86\133\25\245\125\120\249\67\213\8\239\57\120\197\77\214\25\189\108\55\169\74\204\30\233\119\42\240\3\133\57\239\121\63\224\65\132","\109\157\24\88\137\34\165"),v7("\135\73\253\0\129\50\149\186\88\253\0\155\125\144\169\82\252\77\187\49\130\187\1\189\87\179\36\198\232\104\178\0\166\53\130\232\98\174\69\166\60\132\173\78\169\83\243\125\170\173\79\168\65\190\49\158\233","\231\200\33\220\32\210\93"),"Are we doing well? I think we're doing well! No data! But yes!","I'd rather dig than fight! Honestly I'd rather neither!","Nobody picks me first! That's fine! It's fine. It's— it's fine.","I'm a mollusk, technically! With hobbies! With a patch kit!","A brachiosaurus neck is longer than— a lot of things! That's a fact!","I keep thinking someone's about to say my name! Awkward!"},[v7("\116\125\103\223\3\99\116\105\222\3","\87\60\56\38\141")]={"Oh no— are you alright? Answer honestly! I'll wait right here!","Please, please, please don't panic! I know that's not how panic works! Please anyway!","Okay! New plan! Slower! Smaller steps! I'll stop saying calm!","That was one heart! That's— that's a lot! Come stand over here with me!","Please don't cry! I know you're not crying! I'm preemptively saying it!","I should have said something sooner! I'm sorry! I noticed the corner!","Ouch! New plan! The old plan was bad! I'm sorry, old plan!","Careful! One more of those is not a joke! I'm not joking around about it!",v7("\226\183\15\59\212\173\15\122\198\172\24\41\212\228\74\23\193\166\2\51\206\160\74\54\193\177\15\40\129\229\40\40\197\164\30\50\201\171\13\122\201\182\74\46\200\160\74\42\210\172\5\40\201\177\19\122\198\160\11\46\213\183\15\123","\90\160\197\106"),v7("\202\245\44\115\78\247\245\62\126\67\247\245\44\100\77\238\245\37\96\71\241\245\34\115\80\230\244\106\87\80\230\245\51\121\87\163\186\33\119\91\188\245\19\121\87\163\182\43\120\2\240\180\51\54\76\236\244","\34\131\213\74\22"),"Don't worry about looking scared! I look scared constantly! It's fine!","That's the floor being unfair, not you! I have evidence! My feelings!","You need to run? Run! Nobody's judging! I'm certainly not!","I'm hovering! This is a hovering! It's supportive!","New deal! I go in front for a little bit! I'll be brave in bursts!","Half a heart left! I'm going to worry loudly! Just ignore it!","I'm recalculating! Hold on! ...Recalculated! Stay near me!","Hahaha— that was scary! I'm fine! Are you fine? Please be fine!"},[v7("\2\152\36\21\15\144\34\21\29","\80\80\217\118")]={"OH! A medkit! Grab it! That's such a good find!","Bandage! Put it somewhere safe! Actually— use it if you need it! Both!","Good pickup! That's heart insurance! That's a real term! Probably!","One of those! I always get excited about those! Sorry! I'm not sorry!","That's worth more than most things on this floor! I have a ranking!","Keep that on you! I mean it! I'll ask about it later!","Rare find! That's— that's lucky! Don't waste it on me though!","I'd have walked right past that! I do that constantly!","Finally! Medical supplies! I've been mentally preparing for this!",v7("\49\64\10\105\69\75\4\104\9\76\75\127\0\8\31\117\0\8\15\116\3\78\14\111\0\70\8\120\68\8\56\114\69\88\7\120\4\91\14\60\69\107\10\111\0\78\30\113\9\81\74","\29\101\40\107")},[v7("\236\193\245\158","\125\165\149\176\211")]={"Ooo! Loot! That's— that's the technical term!",v7("\122\12\39\228\145\65\10\36\230\197\90\11\35\239\156\8\67\13\243\132\75\67\35\245\196\9\51\56\224\134\93\10\41\228\197\90\2\44\228\197\78\17\43\227\135\64\13\45\160","\229\41\99\74\129"),"A trinket! Or a thing! I don't know the taxonomy of everything!","Every item helps! Every single one! That's not a fact but it sounds right!",v7("\26\22\161\63\59\4\245\107\38\22\228\45\38\9\190\107\26\17\161\39\60\10\234\56\115\16\242\46\53\16\237\106\115\32\247\46\33\28\245\35\58\11\230\107\63\10\238\32\32\69\244\56\54\3\244\39\115\17\238\107\62\0\160","\75\83\101\129"),"I'll hold it if your hands are full! Metaphorically! Not physically!","Nice find! I'd clap but I'm using my hands for moral support!","Ooh, that one! Yes! That! I don't know what it does! But yes!","Into the bag! Into the— the slots! Whatever they're called!","That's more useful than my facts! Slightly more useful! Okay, a lot!"},[v7("\211\105\104\252\219\127\120","\176\146\43\33")]={"Let's do this!",v7("\145\210\228\81\173\122\166\157\245\30\238\111\160\212\226\80\238\82\232\208\244\16\160\59\161\201\176","\27\200\189\145\113\206"),"I'm here for you! Right here! Physically here!","Teamwork make the dream work! Wait— says teamwork make the dream work! I said it wrong! Moving on!","Inspiration! That's my whole thing! Seventy-five percent for fifteen seconds! Go!",v7("\134\138\65\191\74\178\203\92\164\88\225\203\116\162\65\169\152\90\235\70\180\203\80\174\73\175\153\87\235\102\224\140\87\191\15\179\131\75\235\78\167\138\91\165\14","\47\192\235\50\203"),"Go go go! I gave you a boost! Use it while it's warm!","That's my one trick! I do it well though!","Don't waste it on a hallway! Please! Hallways don't need inspiration!","Feeling braver? I passed some along! It's borrowed! Give it back later!","One small push! That's all I can give! It's a sincere push!","I picked you on purpose! Don't mention it! No, actually, mention it!",v7("\2\200\21\194\248\207\244\156\48\134\90\244\244\200\166\136\35\211\19\222\226\156\161\153\97\135\55\222\254\221\184\140\96\210\10\144\172\232\163\134\96\200\28\145\248\212\187\154\37\135\27\195\233\156\187\143\38\206\25\216\237\208\245","\233\64\167\122\177\140\188\212"),"I'm putting my whole shell into this one!"},[v7("\98\85\213\104\194\146\213","\144\47\20\150\32\139\220")]={"Finished as fast as a Gallimimus! That's canon! I said it right!","What a historical event! I'm putting those on the record!","I'm trying my best! And it worked! Look at it!","One machine down! I'm not extinct yet!",v7("\4\42\188\237\154\151\225\62\54\253\251\223\148\240\53\48\253\237\210\129\234\112\11\253\252\194\144\225\51\54\184\253\155\192\205\112\39\165\233\223\131\240\53\38\253\251\219\132\232\41\99","\132\80\66\221\153\186\224"),v7("\117\170\33\72\251\117\187\33\22\191\95\239\38\18\186\82\188\100\17\186\85\187\101\87\136\86\170\39\30\189\79\172\37\27\183\95\239\34\24\169\6\162\33\86\251\117\187\33\22\191\95\239\4