9\50\21\51\2\222\68\54\71\118\115","\82\178\33\87\52\19"),v7("\101\177\168\119\101\12\177\224\127\112\64\226\235\114\117\92\178\237\126\35\12\129\224\127\127\71\226\228\123\104\73\176\169\58\81\67\180\225\116\123\12\164\225\104\111\88\227","\28\44\194\136\26"),v7("\85\57\68\9\99\134\95\142\126\124\7\5\122\143\90\192\117\119\64\70\119\202\93\193\111\106\78\10\54\152\82\201\116\109\7\8\121\157\26\142\85\119\84\18\115\139\95\143\60\77\79\15\101\203","\174\28\25\39\102\22\234\59"),v7("\225\76\2\221\142\145\204\9\23\215\142\135\206\72\25\214\143\198\250\72\9\209\192\129\137\65\21\202\203\198\222\76\80\223\193\198\200\78\17\209\192\199","\230\169\41\112\184\174"),"Everyone here? Count off! I'll count! ...I counted wrong!","One floor closer! We're doing okay! I'm choosing to believe that!",v7("\238\193\112\174\23\6\147\65\197\211\52\254\62\29\192\91\207\202\53\184\29\6\147\73\197\203\97\173\6\17\195\92\139\132\90\172\82\16\220\15\196\203\97\254\30\29\192\91\207\202\52\254\55\29\199\71\207\214\53\169\19\13\146","\47\170\164\21\222\114\116\179"),v7("\217\142\139\208\248\149\136\216\233\199\139\218\242\136\159\154\189\148\140\219\248\199\139\215\254\147\158\151\189\174\205\222\252\145\136\150\238\136\205\219\252\137\148\150\251\134\142\194\238\198","\182\157\231\237"),v7("\219\243\15\165\181\252\0\175\250\232\77\224\198\239\31\176\252\249\5\175\224\233\0\185\181\244\5\163\240\187","\192\149\154\108")},[v7("\205\214\200\14\2\23\50\205\203\200","\97\153\153\135\64\93\86")]={"Astro asked if I was alright! ME! I said Huh?? OH! You're asking me?!",v7("\39\77\198\58\246\105\130\202\70\77\221\104\250\40\135\212\71\30\251\104\248\58\128\220\2\30\212\39\235\105\138\153\2\76\215\41\244\105\132\215\5\91\146\41\247\45\203\202\7\87\214\104\237\40\134\220\70\95\146\32\236\39\143\203\3\90\146\62\252\37\132\218\15\76\211\56\237\38\153\202\71","\185\102\62\178\72\153\73\235"),"I'm doing better knowing I got Astro around! That's a real sentence I said out loud!",v7("\85\169\63\160\123\250\37\1